<script setup lang="ts">import{computed}from'vue';import type{DecisionAnalysis,Eligibility,OptionAnalysis}from'../../core/models';import RegretCurve from'./RegretCurve.vue';const props=defineProps<{analysis:DecisionAnalysis;stale:boolean}>();const ELIGIBILITY_LABEL:Record<Eligibility,string>={eligible:'合格',conditional:'条件候选',ineligible:'暂无资格'};const gated=computed(()=>props.analysis.options.some(o=>(o.gate?.checks??[]).length>0));const blocked=computed(()=>Boolean(props.analysis.pending?.length));const eligibilityOf=(item:OptionAnalysis):Eligibility=>item.gate?.eligibility??'eligible';const issuesOf=(item:OptionAnalysis)=>(item.gate?.checks??[]).filter(c=>c.verdict!=='pass');const passedCount=(item:OptionAnalysis)=>(item.gate?.checks??[]).filter(c=>c.verdict==='pass').length;function rankOf(item:OptionAnalysis):number|null{const pool=props.analysis.options.filter(o=>eligibilityOf(o)!=='ineligible');const index=pool.indexOf(item);return index<0?null:index+1}</script>
<template><section class="results"><div v-if="stale" class="stale-note">输入已变化，下方是上一次分析结果，请重新计算。</div><div class="recommendation" :class="{tentative:analysis.tentative,blocked}"><span>THE LEAST REGRETFUL PATH</span><h2>{{blocked?'暂无合格方案':'最不后悔建议'}}</h2><p>{{analysis.recommendation}}</p><aside v-for="note in analysis.gateNotes??[]" :key="note" class="gate-note">{{note}}</aside><aside v-for="conflict in analysis.conflicts??[]" :key="conflict" class="conflict-note">{{conflict}}</aside><aside v-for="notice in analysis.notices" :key="notice">{{notice}}</aside></div><div v-if="blocked" class="pending-list"><div class="pending-head"><span>TO QUALIFY</span><h3>待解决条件</h3><p>以下必须条件暂无方案满足。解决差距、补充缺失判断，或调整条件后重新推演，才会给出推荐。</p></div><article v-for="pending in analysis.pending" :key="pending.condition.id"><b>{{pending.label}}</b><small v-if="pending.condition.note">依据：{{pending.condition.note}}</small><ul><li v-for="gap in pending.gaps" :key="gap.optionId">「{{gap.optionName}}」<template v-if="gap.gap===null">缺少该指标的判断，先补充评估</template><template v-else>当前 {{gap.actual}}，差 {{gap.gap}}</template></li></ul><p v-if="pending.closestOption" class="closest">最接近：「{{pending.closestOption}}」{{pending.closestGap?`（差 ${pending.closestGap}）`:'（已在临界带内，确认即可）'}}</p></article></div><RegretCurve :options="analysis.options"/><div class="score-grid"><article v-for="item in analysis.options" :key="item.option.id" :class="`gate-${eligibilityOf(item)}`"><span>{{rankOf(item)?`#0${rankOf(item)}`:'不参与推荐'}}</span><em v-if="gated" class="gate-badge" :class="eligibilityOf(item)">{{ELIGIBILITY_LABEL[eligibilityOf(item)]}}</em><h3>{{item.option.name}}</h3><b>{{item.total}}<small>/100</small></b><div><i v-for="p in item.points" :key="p.horizon">{{p.horizon}}年 {{p.score}}</i></div><ul v-if="issuesOf(item).length" class="gate-reasons"><li v-for="check in issuesOf(item)" :key="check.condition.id" :class="check.verdict">{{check.reason}}<small v-if="check.condition.note">依据：{{check.condition.note}}</small></li></ul><p v-else-if="gated" class="gate-ok">满足全部 {{passedCount(item)}} 项必须条件。</p></article></div><div class="rehearsals"><article v-for="item in analysis.options" :key="item.option.id"><h3>{{item.option.name}} · 后悔预演</h3><div v-for="card in item.cards" :key="card.horizon"><b>{{card.horizon}} 年后</b><p>{{card.regret}}</p><small>{{card.trigger}} {{card.reversibility}}；{{card.action}}</small></div></article></div></section></template>
